# owner: platform
"""Contact sheet for substitute teachers."""

from typing import Iterable, List

from rosterkit.errors import ProjectError
from rosterkit.models import Student


def _require_emails(roster: List[Student]) -> None:
    if not roster:
        raise ProjectError("no students to list")
    for item in roster:
        if not item.email:
            raise ProjectError(f"no email for {item.display_name}")


def _align(cells: List[tuple]) -> List[str]:
    widths = [max(map(len, column)) for column in zip(*cells)]
    lines = ["  ".join(text.ljust(size) for text, size in zip(row, widths)) for row in cells]
    return [line.rstrip() for line in lines]


# ---
def contact_rows(students: Iterable[Student]) -> List[str]:
    """Rows of name, section and email in columns, sorted by name."""
    roster = sorted(students, key=lambda item: item.display_name)
    _require_emails(roster)
    return _align([(item.display_name, item.section, item.email) for item in roster])
