# owner: platform
import unittest

from rosterkit.contacts import contact_rows
from rosterkit.errors import ProjectError
from rosterkit.models import Student


def _student(last, first, section="A1", email="x@example.org"):
    return Student("id", last, first, section, email)


class ContactRowTests(unittest.TestCase):
    def test_rows_are_sorted_and_aligned(self):
        rows = contact_rows([_student("Zed", "Al", "B2", "z@e.org"), _student("Abe", "Bo")])
        self.assertEqual(rows, ["Abe, Bo  A1  x@example.org", "Zed, Al  B2  z@e.org"])

    def test_missing_email_names_the_student(self):
        with self.assertRaisesRegex(ProjectError, "Abe, Bo"):
            contact_rows([_student("Abe", "Bo", email=None)])

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            contact_rows([])


if __name__ == "__main__":
    unittest.main()
